{
  "schema": "threatline.threatmodel.v1",
  "issueKey": "EVAL-05",
  "sketch": {
    "components": ["Internal admin portal", "SAML service provider module", "Role mapping / authorization logic", "Session manager"],
    "dataStores": ["Admin portal session store"],
    "externalServices": ["Corporate identity provider (SAML IdP)"],
    "trustBoundaries": ["Internet to admin portal", "Admin portal to corporate identity provider", "Unauthenticated browser POST of SAML response to assertion consumer endpoint"],
    "dataClasses": ["credentials"],
    "exposure": "public",
    "llmFeatures": false
  },
  "threats": [
    {
      "stride": "Spoofing",
      "title": "Forged SAML assertion accepted because signature is not fully validated",
      "scenario": "The design says employees sign in through SAML but does not state that the portal verifies the assertion signature against a pinned IdP certificate. An attacker who can reach the internet-facing assertion consumer endpoint crafts or edits a SAML response (self-signed assertion, stripped signature, or XML signature wrapping that keeps a valid signature over a different element) and posts it. The portal trusts the attacker-supplied identity and logs them in as any employee, including an administrator.",
      "component": "SAML service provider module",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        {
          "quote": "Employees sign in to the internal admin portal through SAML single sign-on with the corporate identity provider."
        },
        {
          "quote": "The portal is reachable from the internet."
        }
      ],
      "cwe": ["CWE-347", "CWE-290"],
      "plainLanguage": "If the portal does not properly check the digital signature on the login message, someone can write their own and log in as anybody.",
      "requirement": {
        "title": "Verify SAML assertion signatures against a pinned IdP certificate",
        "given": "a SAML response is posted to the admin portal assertion consumer endpoint",
        "when": "the signature is missing, self-signed, signed by an untrusted key, or does not cover the assertion element actually used",
        "then": "the portal rejects the login, creates no session, and records the failure"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Admin access granted from an attacker-controllable role attribute in the assertion",
      "scenario": "The portal decides admin access purely from the role attribute in the assertion. Anyone who can influence that attribute - a user who can edit their own IdP directory profile, a helpdesk operator, an attacker who modifies an unsigned or partially signed attribute statement, or an attacker replaying an assertion from a less trusted IdP - becomes a portal administrator. No second check against a server-side authorization list is described.",
      "component": "Role mapping / authorization logic",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        {
          "quote": "After login, the portal reads the role attribute from the assertion to decide admin access."
        }
      ],
      "cwe": ["CWE-269", "CWE-807"],
      "plainLanguage": "Admin rights come straight from a field in the login message, so anyone who can change that field becomes an admin.",
      "requirement": {
        "title": "Authorize admin access from server-side state, not only the assertion attribute",
        "given": "a user authenticates through SAML with a role attribute claiming admin",
        "when": "the portal decides whether to grant admin functions",
        "then": "it grants admin only if the authenticated subject also appears in the portal's own administrator list, and otherwise grants normal user access"
      }
    },
    {
      "stride": "Spoofing",
      "title": "Assertion issued for another application accepted by the portal",
      "scenario": "The design does not require checking Issuer, Audience/AudienceRestriction, Destination or Recipient. An employee or attacker who obtains a valid assertion issued for a different, lower-value service provider in the same corporate IdP posts it to the internet-facing admin portal. Because any well-formed assertion from any trusted-looking issuer is accepted, they obtain an admin portal session without ever being authorized for the portal.",
      "component": "SAML service provider module",
      "likelihood": 3,
      "impact": 5,
      "evidence": [
        {
          "quote": "Employees sign in to the internal admin portal through SAML single sign-on with the corporate identity provider."
        }
      ],
      "cwe": ["CWE-287", "CWE-1270"],
      "plainLanguage": "A login ticket meant for a different app could be reused to get into the admin portal.",
      "requirement": {
        "title": "Validate issuer, audience and destination on every assertion",
        "given": "a signed SAML assertion arrives at the admin portal",
        "when": "the Issuer is not the configured corporate IdP, or the AudienceRestriction or Destination does not match this portal's entity id and ACS URL",
        "then": "the portal rejects the assertion and does not create a session"
      }
    },
    {
      "stride": "Spoofing",
      "title": "Captured assertion replayed to create a new admin session",
      "scenario": "No one-time-use, NotBefore/NotOnOrAfter or InResponseTo handling is described. An attacker who captures a SAML response from browser history, a proxy log, a referrer, or a shared workstation re-posts the same response to the internet-facing portal later and receives a fresh session as that employee, including admin rights carried in the role attribute.",
      "component": "SAML service provider module",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        {
          "quote": "The portal is reachable from the internet."
        },
        {
          "quote": "After login, the portal reads the role attribute from the assertion to decide admin access."
        }
      ],
      "cwe": ["CWE-294"],
      "plainLanguage": "Someone could reuse a stolen login message to log in again as that employee.",
      "requirement": {
        "title": "Reject replayed and expired assertions",
        "given": "a SAML response that was already consumed or whose validity window has passed",
        "when": "it is posted to the assertion consumer endpoint",
        "then": "the portal rejects it, keyed on the assertion id and its NotOnOrAfter, and logs a replay attempt"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Internet-exposed admin portal with no additional access restriction or step-up authentication",
      "scenario": "An admin portal described as internal is reachable from the internet, so every attacker on the internet can reach the login and assertion endpoints and attack them directly (credential stuffing against the IdP, phishing an employee for an SSO session, or probing the SAML parser). Nothing in the design restricts the portal to the corporate network, a VPN or allow-listed egress, and no step-up or phishing-resistant MFA is required before admin functions.",
      "component": "Internal admin portal",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        {
          "quote": "The portal is reachable from the internet."
        },
        {
          "quote": "Employees sign in to the internal admin portal through SAML single sign-on with the corporate identity provider."
        }
      ],
      "cwe": ["CWE-1327", "CWE-308"],
      "plainLanguage": "An internal admin tool is open to the whole internet, so anyone can attack its login.",
      "requirement": {
        "title": "Restrict the admin portal and require phishing-resistant MFA for admin functions",
        "given": "a request to the admin portal from outside the corporate network",
        "when": "the request reaches the portal or an admin function is invoked",
        "then": "the portal is only reachable through the approved network path, and admin functions require a recent phishing-resistant MFA assertion from the IdP"
      }
    },
    {
      "stride": "Tampering",
      "title": "Unsolicited IdP-initiated SAML response used for login CSRF or session fixation",
      "scenario": "Because the portal accepts SAML responses on an internet-reachable endpoint with no described request correlation, an attacker can make a victim's browser post an assertion for an account the attacker controls (login CSRF), so the victim acts in the attacker's session, or post the victim's assertion into a session the attacker can later reach if the session identifier is not rotated at login.",
      "component": "SAML service provider module / Session manager",
      "likelihood": 3,
      "impact": 3,
      "evidence": [
        {
          "quote": "The portal is reachable from the internet."
        }
      ],
      "cwe": ["CWE-384", "CWE-352"],
      "plainLanguage": "An attacker can force your browser to be logged in as them, or keep hold of your session after you log in.",
      "requirement": {
        "title": "Correlate SAML responses with a portal-initiated request and rotate the session",
        "given": "a SAML response arrives at the admin portal",
        "when": "it has no matching InResponseTo/RelayState for a request this portal started",
        "then": "the portal rejects it, and on every successful login it issues a brand new session identifier and discards the previous one"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "XML parsing of the assertion exposes internal files and services",
      "scenario": "The portal must parse attacker-supplied XML from the internet to read the role attribute. If external entity resolution or DTD processing is left enabled, an attacker posts a crafted SAML response with an external entity and the parser reads local files (configuration, IdP signing keys, secrets) or makes requests to internal services the internet-facing portal can reach, returning or leaking the content.",
      "component": "SAML service provider module (XML parser)",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        {
          "quote": "After login, the portal reads the role attribute from the assertion to decide admin access."
        },
        {
          "quote": "The portal is reachable from the internet."
        }
      ],
      "cwe": ["CWE-611", "CWE-776"],
      "plainLanguage": "The login message is XML; if the parser is not locked down, an attacker can use it to read files off the server.",
      "requirement": {
        "title": "Parse SAML XML with entity and DTD processing disabled",
        "given": "a SAML response containing a DTD, external entity or entity expansion",
        "when": "the portal parses it",
        "then": "the parser rejects the document without resolving entities or making network requests, and resource limits abort oversized documents"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Stale admin role kept for the whole session after the IdP revokes it",
      "scenario": "Admin access is decided once, from the role attribute read at login. When an employee is demoted, leaves, or is disabled in the corporate IdP, nothing described re-evaluates the role or terminates the existing portal session, so a long-lived session on an internet-reachable portal keeps full admin rights until it happens to expire. A departing insider can deliberately open a session before leaving.",
      "component": "Session manager / Role mapping",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        {
          "quote": "After login, the portal reads the role attribute from the assertion to decide admin access."
        }
      ],
      "cwe": ["CWE-613"],
      "plainLanguage": "If someone loses admin rights at the company, their open portal session still has them.",
      "requirement": {
        "title": "Re-check role and honour revocation during the session",
        "given": "an active admin session in the portal",
        "when": "the user's role or account status changes at the corporate identity provider, or a bounded re-authentication interval elapses",
        "then": "the portal re-evaluates the role and terminates or downgrades the session before the next admin action"
      }
    }
  ]
}
```
